import { useEffect, useRef, useState } from 'react';
import recorded from './correctionCase.json';
import { reducedMotion } from './navigation';

/**
 * Home-page replay of one recorded case from experiments/statguard_correction_v0.1 (generated by export_case.py):
 * the model's wrong answer → StatGuard's recomputation → the evidence sent back → the corrected answer,
 * next to what happened when the model was only told to re-check. Nothing here is typed by hand.
 */
type Case = {
  source: { case: string; model: string };
  dataset: { rows: number };
  question: string;
  original: { answer: string };
  recompute: { claimed: string; value: string; unit: string; expression: string; used_rows: number; difference: { absolute: string; relative_percent: string } | null };
  corrected: { answer: string; claimed: string };
  recheck_only: { answer: string; correct: boolean };
};
const c = recorded as unknown as Case;
const short = (v: string, digits = 4) => String(Number(Number(v).toFixed(digits)));
const sentence = (answer: string) => answer.split('\n').filter(l => l.trim() && !l.includes('최종값'))[0]?.trim() ?? answer;
const finalValue = (answer: string) => (answer.match(/최종값\s*[:：]\s*(.+)/)?.[1] ?? '').trim();

function Marked({ text, mark, tone }: { text: string; mark: string; tone: 'bad' | 'ok' }) {
  const i = text.indexOf(mark);
  if (i < 0) return <>{text}</>;
  return <>{text.slice(0, i)}<mark className={'sg-rp-mark-' + tone}>{mark}</mark>{text.slice(i + mark.length)}</>;
}

const STEPS = ['AI 답변', 'StatGuard 재계산', '근거 전달', '고친 답변'];

/** All four steps are shown at once (no scroll pinning); they fade in once when the section comes into view. */
export default function CorrectionReplay() {
  const [step, setStep] = useState(STEPS.length), box = useRef<HTMLElement>(null);
  useEffect(() => {
    const el = box.current;
    if (!el || typeof IntersectionObserver !== 'function' || reducedMotion()) return;
    setStep(0);
    const io = new IntersectionObserver(entries => { if (entries.some(e => e.isIntersecting)) { setStep(STEPS.length); io.disconnect(); } }, { threshold: 0.2 });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  const value = short(c.recompute.value), diff = c.recompute.difference;
  const on = (i: number) => (step > i ? ' is-on' : '');
  return <section ref={box} className="sg-section sg-replay sg-replay-flat" aria-labelledby="replay-heading"><div className="sg-replay-stage">
    <header className="sg-h2-block"><p className="sg-h2-eyebrow">실제 사례</p><h2 id="replay-heading">근거를 주면 AI가 스스로 고친다</h2>
      <p className="sg-replay-q">질문 · {c.question}</p></header>
    <ol className="sg-rp-track">
      <li className={'sg-rp-step' + on(0)}><span className="sg-rp-num">1</span><h3>{STEPS[0]}</h3>
        <blockquote><Marked text={sentence(c.original.answer)} mark={c.recompute.claimed} tone="bad"/></blockquote></li>
      <li className={'sg-rp-step' + on(1)}><span className="sg-rp-num">2</span><h3>{STEPS[1]}</h3>
        <p className="sg-rp-big sg-num">{value}{c.recompute.unit}</p>
        <span className="sg-rp-stamp sg-rp-bad">계산 불일치{diff ? ` · 차이 ${short(diff.absolute, 2)}${c.recompute.unit}` : ''}</span></li>
      <li className={'sg-rp-step' + on(2)}><span className="sg-rp-num">3</span><h3>{STEPS[2]}</h3>
        <ul><li>답변의 값 {c.recompute.claimed}</li><li>재계산 값 {value}{c.recompute.unit}</li><li>사용한 행 {c.recompute.used_rows.toLocaleString('ko-KR')}개</li></ul>
        <p className="sg-rp-note">정답이 아니라 계산 근거만 보냄</p></li>
      <li className={'sg-rp-step' + on(3)}><span className="sg-rp-num">4</span><h3>{STEPS[3]}</h3>
        <blockquote><Marked text={sentence(c.corrected.answer)} mark={c.corrected.claimed} tone="ok"/></blockquote>
        <span className="sg-rp-stamp sg-rp-ok">계산 일치</span></li>
    </ol>
    <div className={'sg-rp-compare' + on(3)} aria-label="근거 없이 다시 확인만 시킨 경우">
      <strong>근거 없이 “다시 확인해 보세요”만 보내면</strong>
      <span>{finalValue(c.original.answer)} → {finalValue(c.recheck_only.answer)}</span>
      <span className={'sg-rp-stamp ' + (c.recheck_only.correct ? 'sg-rp-ok' : 'sg-rp-bad')}>{c.recheck_only.correct ? '고쳐짐' : '그대로 틀림'}</span>
    </div>
  </div></section>;
}
